SET client_min_messages TO NOTICE;

\echo 'Upgrading 3DCityDB schemas to version 5.2.0 ...'
\echo

DO $$
DECLARE
  schema_name text;
BEGIN
  FOR schema_name IN
    SELECT nspname FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relname = 'database_srs' AND c.relkind = 'r'
  LOOP
    EXECUTE format('set search_path to %I, citydb_pkg, public', schema_name);
    RAISE NOTICE 'Upgrading schema "%" ...', schema_name;

    RAISE NOTICE 'Setting "objectclass.is_toplevel" to true for GenericThematicSurface ...';
    UPDATE objectclass SET is_toplevel = 1 WHERE id = 203;

    RAISE NOTICE 'Updating table "objectclass" ...';
    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:AbstractObject","description":"AbstractObject is the abstract superclass of all feature and object types.","table":"feature","properties":[{"name":"id","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the internal database ID of the object.","value":{"column":"id","type":"integer"},"minOccurs":1,"maxOccurs":1},{"name":"objectId","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the identifier of the object that is unique within the database. Using a globally unique identifier is recommended.","value":{"column":"objectid","type":"string"},"maxOccurs":1},{"name":"identifier","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies an optional identifier of the object that is globally unique.","value":{"column":"identifier","type":"string"},"maxOccurs":1},{"name":"codeSpace","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the code space of the identifier, typically a reference to the maintaining authority.","value":{"column":"identifier_codespace","type":"string"},"parent":1,"minOccurs":1,"maxOccurs":1},{"name":"envelope","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the minimum bounding box that encloses the entire object.","value":{"column":"envelope","type":"core:Envelope"},"maxOccurs":1},{"name":"objectClassId","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the internal object class ID of the object.","value":{"column":"objectclass_id","type":"integer"},"maxOccurs":1},{"name":"lastModificationDate","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Indicates the date and time at which the object was last updated in the database.","value":{"column":"last_modification_date","type":"timestamp"},"maxOccurs":1},{"name":"updatingPerson","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the person who last updated the object in the database.","value":{"column":"updating_person","type":"string"},"maxOccurs":1},{"name":"reasonForUpdate","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the reason for the last update of the object in the database.","value":{"column":"reason_for_update","type":"string"},"maxOccurs":1},{"name":"lineage","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the lineage information of the object.","value":{"column":"lineage","type":"string"},"maxOccurs":1},{"name":"description","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies a text description of the object.","type":"core:StringOrRef","maxOccurs":1},{"name":"descriptionReference","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies a reference to a remote text description of the object.","type":"core:Reference","maxOccurs":1},{"name":"name","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies a label or identifier of the object, commonly a descriptive name.","type":"core:Code"}]}'
    WHERE ID = 2;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:Address","description":"Address represents an address of a city object.","table":"address","properties":[{"name":"objectId","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the identifier of the address that is unique within the database. Using a globally unique identifier is recommended.","value":{"column":"objectid","type":"string"},"maxOccurs":1},{"name":"identifier","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies an optional identifier of the address that is globally unique.","value":{"column":"identifier","type":"string"},"maxOccurs":1},{"name":"codeSpace","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the code space of the identifier, typically a reference to the maintaining authority.","value":{"column":"identifier_codespace","type":"string"},"parent":1,"minOccurs":1,"maxOccurs":1},{"name":"street","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the name of the street.","value":{"column":"street","type":"string"},"maxOccurs":1},{"name":"houseNumber","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the house number.","value":{"column":"house_number","type":"string"},"maxOccurs":1},{"name":"poBox","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the post office box number.","value":{"column":"po_box","type":"string"},"maxOccurs":1},{"name":"zipCode","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the ZIP code.","value":{"column":"zip_code","type":"string"},"maxOccurs":1},{"name":"city","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the name of the city.","value":{"column":"city","type":"string"},"maxOccurs":1},{"name":"state","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the name of the state.","value":{"column":"state","type":"string"},"maxOccurs":1},{"name":"country","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the name of the country.","value":{"column":"country","type":"string"},"maxOccurs":1},{"name":"multiPoint","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to the MultiPoint geometry of the Address. The geometry relates the address spatially to a city object.","value":{"column":"multi_point","type":"core:MultiPoint"},"maxOccurs":1}]}'
    WHERE ID = 4;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:AbstractFeatureWithLifespan","description":"AbstractFeatureWithLifespan is the base class for all features. This class allows the optional specification of the real-world and database times for the existence of each feature.","table":"feature","properties":[{"name":"creationDate","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Indicates the date and time at which the feature was added to the database.","value":{"column":"creation_date","type":"timestamp"},"maxOccurs":1},{"name":"terminationDate","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Indicates the date and time at which the feature was removed from the database.","value":{"column":"termination_date","type":"timestamp"},"maxOccurs":1},{"name":"validFrom","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Indicates the date and time at which the feature started to exist in the real world.","value":{"column":"valid_from","type":"timestamp"},"maxOccurs":1},{"name":"validTo","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Indicates the date and time at which the feature ended to exist in the real world.","value":{"column":"valid_to","type":"timestamp"},"maxOccurs":1}]}'
    WHERE ID = 6;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:AbstractCityObject","description":"AbstractCityObject is the abstract superclass of all thematic classes.","table":"feature","properties":[{"name":"externalReference","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"References external objects in other information systems that have a relation to the city object.","type":"core:ExternalReference"},{"name":"generalizesTo","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates generalized representations of the same real-world object in different Levels of Detail to the city object. The direction of this relation is from the city object to the corresponding generalized city objects.","type":"core:FeatureProperty","target":"core:AbstractCityObject","relationType":"relates"},{"name":"relativeToTerrain","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Describes the vertical position of the city object relative to the surrounding terrain.","type":"core:String","maxOccurs":1},{"name":"relativeToWater","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Describes the vertical position of the city object relative to the surrounding water surface.","type":"core:String","maxOccurs":1},{"name":"relatedTo","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates other city objects to the city object. It also describes how the city objects are related to each other.","type":"core:CityObjectRelation"},{"name":"appearance","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates appearances to the city object.","type":"core:AppearanceProperty"},{"name":"dynamizer","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates Dynamizer objects to the city object. These allow timeseries data to override static attribute values of the city object.","type":"core:FeatureProperty","target":"core:AbstractDynamizer","relationType":"contains"}]}'
    WHERE ID = 7;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:AbstractSpace","description":"AbstractSpace is the abstract superclass for all types of spaces. A space is an entity of volumetric extent in the real world.","table":"feature","properties":[{"name":"spaceType","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the degree of openness of a space.","type":"core:String","maxOccurs":1},{"name":"volume","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies qualified volumes related to the space.","type":"core:QualifiedVolume"},{"name":"area","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies qualified areas related to the space.","type":"core:QualifiedArea"},{"name":"boundary","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to surfaces that bound the space.","type":"core:FeatureProperty","target":"core:AbstractSpaceBoundary","relationType":"contains"},{"name":"lod0Point","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D Point geometry that represents the space in Level of Detail 0.","type":"core:GeometryProperty","target":"core:Point","maxOccurs":1},{"name":"lod0MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiSurface geometry that represents the space in Level of Detail 0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod0MultiCurve","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiCurve geometry that represents the space in Level of Detail 0.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1},{"name":"lod1Solid","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D Solid geometry that represents the space in Level of Detail 1.","type":"core:GeometryProperty","target":"core:AbstractSolid","maxOccurs":1},{"name":"lod2Solid","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D Solid geometry that represents the space in Level of Detail 2.","type":"core:GeometryProperty","target":"core:AbstractSolid","maxOccurs":1},{"name":"lod2MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiSurface geometry that represents the space in Level of Detail 2.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod2MultiCurve","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiCurve geometry that represents the space in Level of Detail 2.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1},{"name":"lod3Solid","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D Solid geometry that represents the space in Level of Detail 3.","type":"core:GeometryProperty","target":"core:AbstractSolid","maxOccurs":1},{"name":"lod3MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiSurface geometry that represents the space in Level of Detail 3.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod3MultiCurve","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiCurve geometry that represents the space in Level of Detail 3.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1}]}'
    WHERE ID = 8;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:AbstractPhysicalSpace","description":"AbstractPhysicalSpace is the abstract superclass for all types of physical spaces. Physical space refers to spaces that are fully or partially bounded by physical objects.","table":"feature","properties":[{"name":"lod1TerrainIntersectionCurve","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiCurve geometry that represents the terrain intersection curve of the physical space in Level of Detail 1.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1},{"name":"lod2TerrainIntersectionCurve","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiCurve geometry that represents the terrain intersection curve of the physical space in Level of Detail 2.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1},{"name":"lod3TerrainIntersectionCurve","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiCurve geometry that represents the terrain intersection curve of the physical space in Level of Detail 3.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1},{"name":"pointCloud","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D PointCloud that represents the physical space.","type":"core:FeatureProperty","target":"core:AbstractPointCloud","relationType":"contains","maxOccurs":1}]}'
    WHERE ID = 10;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:AbstractOccupiedSpace","description":"AbstractOccupiedSpace is the abstract superclass for all types of physically occupied spaces. Occupied space refers to spaces that are partially or entirely filled with matter.","table":"feature","properties":[{"name":"lod1ImplicitRepresentation","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to an implicit geometry that represents the occupied space in Level of Detail 1.","type":"core:ImplicitGeometryProperty","maxOccurs":1},{"name":"lod2ImplicitRepresentation","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to an implicit geometry that represents the occupied space in Level of Detail 2.","type":"core:ImplicitGeometryProperty","maxOccurs":1},{"name":"lod3ImplicitRepresentation","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to an implicit geometry that represents the occupied space in Level of Detail 3.","type":"core:ImplicitGeometryProperty","maxOccurs":1}]}'
    WHERE ID = 12;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:AbstractThematicSurface","description":"AbstractThematicSurface is the abstract superclass for all types of thematic surfaces.","table":"feature","properties":[{"name":"area","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies qualified areas related to the thematic surface.","type":"core:QualifiedArea"},{"name":"lod0MultiCurve","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiCurve geometry that represents the thematic surface in Level of Detail 0.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1},{"name":"lod0MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiSurface geometry that represents the thematic surface in Level of Detail 0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod1MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiSurface geometry that represents the thematic surface in Level of Detail 1.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod2MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiSurface geometry that represents the thematic surface in Level of Detail 2.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod3MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D MultiSurface geometry that represents the thematic surface in Level of Detail 3.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"pointCloud","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a 3D PointCloud that represents the thematic surface.","type":"core:FeatureProperty","target":"core:AbstractPointCloud","relationType":"contains","maxOccurs":1},{"name":"lod4MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSurface geometry that represents the thematic surface in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1}]}'
    WHERE ID = 14;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:CityModel","description":"CityModel is the container for all objects belonging to a city model.","table":"feature","properties":[{"name":"cityObjectMember","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the city objects that are part of the CityModel.","type":"core:FeatureProperty","target":"core:AbstractCityObject","relationType":"contains","maxOccurs":1},{"name":"versionMember","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the different versions of the CityModel.","type":"core:FeatureProperty","target":"core:AbstractVersion","relationType":"contains","maxOccurs":1},{"name":"versionTransitionMember","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the transitions between the different versions of the CityModel.","type":"core:FeatureProperty","target":"core:AbstractVersionTransition","relationType":"contains","maxOccurs":1},{"name":"appearanceMember","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the appearances of the CityModel.","type":"core:AppearanceProperty","maxOccurs":1},{"name":"featureMember","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the feature objects that are part of the CityModel. It allows to include features that are not derived from core:AbstractCityObject.","type":"core:FeatureProperty","target":"core:AbstractFeature","relationType":"contains","maxOccurs":1}]}'
    WHERE ID = 18;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"core:ImplicitGeometry","description":"ImplicitGeometry is a geometry representation where the shape is stored only once as a prototypical geometry. Examples are a tree or other vegetation object, a traffic light or a traffic sign. This prototypic geometry object can be re-used or referenced many times, wherever the corresponding feature occurs in the 3D city model.","table":"implicit_geometry","properties":[{"name":"objectId","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the identifier of the implicit geometry that is unique within the database. Using a globally unique identifier is recommended.","value":{"column":"objectid","type":"string"},"minOccurs":1,"maxOccurs":1},{"name":"mimeType","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the MIME type of the external file that stores the prototypical geometry.","value":{"column":"mime_type","type":"string"},"maxOccurs":1},{"name":"codeSpace","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the code space of the MIME type, typically a dictionary, thesaurus, classification scheme, authority, or pattern for the MIME type.","value":{"column":"mime_type_codespace","type":"string"},"parent":1,"maxOccurs":1},{"name":"libraryObject","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the URI that points to the prototypical geometry stored in an external file.","value":{"column":"reference_to_library","type":"string"},"maxOccurs":1},{"name":"relativeGeometry","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates to a prototypical geometry in a local coordinate system stored in the database.","target":"core:AbstractGeometry","join":{"table":"geometry_data","fromColumn":"relative_geometry_id","toColumn":"id"},"maxOccurs":1},{"name":"appearance","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Relates appearances to the ImplicitGeometry.","target":"app:Appearance","maxOccurs":1,"join":{"table":"appearance","fromColumn":"id","toColumn":"implicit_geometry_id"}}]}'
    WHERE ID = 21;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"dyn:Dynamizer","description":"A Dynamizer is an object that injects timeseries data for an individual attribute of the city object in which it is included. The timeseries data overrides the static value of the referenced city object attribute in order to represent dynamic (time-dependent) variations of its value.","table":"feature","properties":[{"name":"attributeRef","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the attribute of a feature whose value is overridden or replaced by the (dynamic) values specified by the Dynamizer.","type":"dyn:AttributeReference","minOccurs":1,"maxOccurs":1},{"name":"startTime","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the beginning of the time span for which the Dynamizer provides dynamic values.","type":"core:TimePosition","maxOccurs":1},{"name":"endTime","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the end of the time span for which the Dynamizer provides dynamic values.","type":"core:TimePosition","maxOccurs":1},{"name":"dynamicData","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Relates to the timeseries data.","type":"core:FeatureProperty","target":"dyn:AbstractTimeseries","relationType":"contains","maxOccurs":1},{"name":"sensorConnection","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Relates to the sensor API that delivers timeseries data.","type":"dyn:SensorConnection","maxOccurs":1}]}'
    WHERE ID = 100;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"dyn:AbstractTimeseries","description":"AbstractTimeseries is the abstract superclass representing any type of timeseries data.","table":"feature","properties":[{"name":"firstTimestamp","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the beginning of the timeseries.","type":"core:TimePosition","maxOccurs":1},{"name":"lastTimestamp","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the end of the timeseries.","type":"core:TimePosition","maxOccurs":1}]}'
    WHERE ID = 101;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"dyn:AbstractAtomicTimeseries","description":"AbstractAtomicTimeseries represents the attributes and relationships that are common to all kinds of atomic timeseries (GenericTimeseries, TabulatedFileTimeseries, StandardFileTimeseries). An atomic timeseries represents time-varying data of a specific data type for a single contiguous time interval.","table":"feature","properties":[{"name":"observationProperty","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the phenomenon for which the atomic timeseries provides observation values.","type":"core:String","minOccurs":1,"maxOccurs":1},{"name":"uom","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the unit of measurement of the observation values.","type":"core:String","maxOccurs":1}]}'
    WHERE ID = 102;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"dyn:TabulatedFileTimeseries","description":"A TabulatedFileTimeseries represents time-varying data of a specific data type for a single contiguous time interval. The data is provided in an external file referenced in the TabulatedFileTimeseries. The file contains table structured data using an appropriate file format such as comma-separated values (CSV), Microsoft Excel (XLSX) or Google Spreadsheet. The timestamps and the values are given in specific columns of the table. Each row represents a single time-value-pair. A subset of rows can be selected using the idColumn and idValue attributes.","table":"feature","properties":[{"name":"fileLocation","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the URI that points to the external timeseries file.","type":"core:URI","minOccurs":1,"maxOccurs":1},{"name":"fileType","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the format used to represent the timeseries data.","type":"core:Code","minOccurs":1,"maxOccurs":1},{"name":"mimeType","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the MIME type of the external timeseries file.","type":"core:Code","maxOccurs":1},{"name":"valueType","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Indicates the specific type of the timeseries data.","type":"core:String","minOccurs":1,"maxOccurs":1},{"name":"numberOfHeaderLines","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Indicates the number of lines at the beginning of the tabulated file that represent headers.","type":"core:Integer","maxOccurs":1},{"name":"fieldSeparator","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Indicates which symbol is used to separate the individual values in the tabulated file.","type":"core:String","minOccurs":1,"maxOccurs":1},{"name":"decimalSymbol","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Indicates which symbol is used to separate the integer part from the fractional part of a decimal number.","type":"core:String","maxOccurs":1},{"name":"idColumnNo","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the number of the column that stores the identifier of the time-value-pair.","type":"core:Integer","maxOccurs":1},{"name":"idColumnName","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the name of the column that stores the identifier of the time-value-pair.","type":"core:String","maxOccurs":1},{"name":"idValue","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the value of the identifier for which the time-value-pairs are to be selected.","type":"core:String","maxOccurs":1},{"name":"timeColumnNo","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the number of the column that stores the timestamp of the time-value-pair.","type":"core:Integer","maxOccurs":1},{"name":"timeColumnName","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the name of the column that stores the timestamp of the time-value-pair.","type":"core:String","maxOccurs":1},{"name":"valueColumnNo","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the number of the column that stores the value of the time-value-pair.","type":"core:Integer","maxOccurs":1},{"name":"valueColumnName","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the name of the column that stores the value of the time-value-pair.","type":"core:String","maxOccurs":1}]}'
    WHERE ID = 103;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"dyn:StandardFileTimeseries","description":"A StandardFileTimeseries represents time-varying data for a single contiguous time interval. The data is provided in an external file referenced in the StandardFileTimeseries. The data within the external file is encoded according to a dedicated format for the representation of timeseries data such as using the OGC TimeseriesML or OGC Observations & Measurements Standard. The data type of the data has to be specified within the external file.","table":"feature","properties":[{"name":"fileLocation","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the URI that points to the external timeseries file.","type":"core:URI","minOccurs":1,"maxOccurs":1},{"name":"fileType","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the format used to represent the timeseries data.","type":"core:Code","minOccurs":1,"maxOccurs":1},{"name":"mimeType","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the MIME type of the external timeseries file.","type":"core:Code","maxOccurs":1}]}'
    WHERE ID = 104;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"dyn:GenericTimeseries","description":"A GenericTimeseries represents time-varying data in the form of embedded time-value-pairs of a specific data type for a single contiguous time interval.","table":"feature","properties":[{"name":"valueType","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Indicates the specific type of all time-value-pairs that are part of the GenericTimeseries.","type":"core:String","minOccurs":1,"maxOccurs":1},{"name":"timeValuePair","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Relates to the time-value-pairs that are part of the GenericTimeseries.","type":"dyn:AbstractTimeValuePair","minOccurs":1}]}'
