    UPDATE objectclass
    SET SCHEMA = '{"identifier":"dem:ReliefFeature","description":"A ReliefFeature is a collection of terrain components representing the earth''s surface, also known as the Digital Terrain Model.","table":"feature","properties":[{"name":"lod","namespace":"http://3dcitydb.org/3dcitydb/relief/5.0","description":"Indicates the Level of Detail of the ReliefFeature.","type":"core:Integer","minOccurs":1,"maxOccurs":1},{"name":"reliefComponent","namespace":"http://3dcitydb.org/3dcitydb/relief/5.0","description":"Relates to the terrain components that are part of the ReliefFeature.","type":"core:FeatureProperty","target":"dem:AbstractReliefComponent","relationType":"contains","minOccurs":1}]}'
