    UPDATE objectclass
    SET SCHEMA = '{"identifier":"dem:AbstractReliefComponent","description":"An AbstractReliefComponent represents an element of the terrain surface - either a TIN, a raster or grid, mass points or break lines.","table":"feature","properties":[{"name":"lod","namespace":"http://3dcitydb.org/3dcitydb/relief/5.0","description":"Indicates the Level of Detail of the terrain component.","type":"core:Integer","minOccurs":1,"maxOccurs":1},{"name":"extent","namespace":"http://3dcitydb.org/3dcitydb/relief/5.0","description":"Indicates the geometrical extent of the terrain component. The geometrical extent is provided as a 2D Surface geometry.","type":"core:GeometryProperty","target":"core:Polygon","maxOccurs":1}]}'
