    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:AbstractTransportationSpace","description":"AbstractTransportationSpace is the abstract superclass of transportation objects such as Roads, Tracks, Railways, Waterways or Squares.","table":"feature","properties":[{"name":"trafficDirection","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the direction of traffic flow relative to the corresponding linear geometry representation.","type":"core:String","maxOccurs":1},{"name":"occupancy","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Provides information on the residency of persons, vehicles, or other moving features in the transportation space.","type":"core:Occupancy"},{"name":"trafficSpace","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the traffic spaces that are part of the transportation space.","type":"core:FeatureProperty","target":"tran:TrafficSpace","relationType":"contains"},{"name":"auxiliaryTrafficSpace","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the auxiliary traffic spaces that are part of the transportation space.","type":"core:FeatureProperty","target":"tran:AuxiliaryTrafficSpace","relationType":"contains"},{"name":"hole","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the holes that are part of the transportation space.","type":"core:FeatureProperty","target":"tran:Hole","relationType":"contains"},{"name":"marking","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the markings that are part of the transportation space.","type":"core:FeatureProperty","target":"tran:Marking","relationType":"contains"},{"name":"lod1MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSurface geometry that represents the transportation space in Level of Detail 1. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod4MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSurface geometry that represents the transportation space in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1}]}'
    WHERE ID = 600;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:Railway","description":"A Railway is a transportation space used by wheeled vehicles on rails.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the Railway.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the intended purposes of the Railway.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the actual uses of the Railway.","type":"core:Code"},{"name":"section","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the sections that are part of the Railway.","type":"core:FeatureProperty","target":"tran:Section","relationType":"contains"},{"name":"intersection","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the intersections that are part of the Railway.","type":"core:FeatureProperty","target":"tran:Intersection","relationType":"contains"}]}'
    WHERE ID = 601;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:Section","description":"A Section is a transportation space that is a segment of a Road, Railway, Track, or Waterway.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the Section.","type":"core:Code","maxOccurs":1}]}'
    WHERE ID = 602;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:Waterway","description":"A Waterway is a transportation space used for the movement of vessels upon or within a water body.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the Waterway.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the intended purposes of the Waterway.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the actual uses of the Waterway.","type":"core:Code"},{"name":"section","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the sections that are part of the Waterway.","type":"core:FeatureProperty","target":"tran:Section","relationType":"contains"},{"name":"intersection","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the intersections that are part of the Waterway.","type":"core:FeatureProperty","target":"tran:Intersection","relationType":"contains"}]}'
    WHERE ID = 603;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:Intersection","description":"An Intersection is a transportation space that is a shared segment of multiple Road, Track, Railway, or Waterway objects (e.g. a crossing of two roads or a level crossing of a road and a railway).","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the Intersection.","type":"core:Code","maxOccurs":1}]}'
