    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:Square","description":"A Square is a transportation space for unrestricted movement for vehicles, bicycles and/or pedestrians. This includes plazas as well as large sealed surfaces such as parking lots.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the Square.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the intended purposes of the Square.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the actual uses of the Square.","type":"core:Code"}]}'
    WHERE ID = 605;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:Track","description":"A Track is a small path mainly used by pedestrians. Tracks can be segmented into Sections and Intersections.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the Track.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the intended purposes of the Track.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the actual uses of the Track.","type":"core:Code"}]}'
    WHERE ID = 606;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:Road","description":"A Road is a transportation space used by vehicles, bicycles and/or pedestrians.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the Road.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the intended purposes of the Road.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the actual uses of the Road.","type":"core:Code"},{"name":"section","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the sections that are part of the Road.","type":"core:FeatureProperty","target":"tran:Section","relationType":"contains"},{"name":"intersection","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the intersections that are part of the Road.","type":"core:FeatureProperty","target":"tran:Intersection","relationType":"contains"}]}'
    WHERE ID = 607;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:AuxiliaryTrafficSpace","description":"An AuxiliaryTrafficSpace is a space within the transportation space not intended for traffic purposes.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the AuxiliaryTrafficSpace.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the intended purposes of the AuxiliaryTrafficSpace.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the actual uses of the AuxiliaryTrafficSpace.","type":"core:Code"},{"name":"granularity","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Defines whether auxiliary traffic spaces are represented by individual ways or by individual lanes, depending on the desired level of spatial and semantic decomposition.","type":"core:String","minOccurs":1,"maxOccurs":1}]}'
    WHERE ID = 608;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:ClearanceSpace","description":"A ClearanceSpace represents the actual free space above a TrafficArea within which a mobile object can move without contacting an obstruction.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the ClearanceSpace.","type":"core:Code","maxOccurs":1}]}'
    WHERE ID = 609;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:TrafficSpace","description":"A TrafficSpace is a space in which traffic takes place. Traffic includes the movement of entities such as trains, vehicles, pedestrians, ships, or other transportation types.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the TrafficSpace.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the intended purposes of the TrafficSpace.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the actual uses of the TrafficSpace.","type":"core:Code"},{"name":"granularity","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Defines whether traffic spaces are represented by individual ways or by individual lanes, depending on the desired level of spatial and semantic decomposition.","type":"core:String","minOccurs":1,"maxOccurs":1},{"name":"trafficDirection","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the direction of traffic flow relative to the corresponding linear geometry representation.","type":"core:String","maxOccurs":1},{"name":"occupancy","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Provides information on the residency of persons, vehicles, or other moving features in the TrafficSpace.","type":"core:Occupancy"},{"name":"predecessor","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the predecessor(s) of the TrafficSpace.","type":"core:FeatureProperty","target":"tran:TrafficSpace","relationType":"relates"},{"name":"successor","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the successor(s) of the TrafficSpace.","type":"core:FeatureProperty","target":"tran:TrafficSpace","relationType":"relates"},{"name":"clearanceSpace","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Relates to the clearance spaces that are part of the TrafficSpace.","type":"core:FeatureProperty","target":"tran:ClearanceSpace","relationType":"contains"}]}'
    WHERE ID = 610;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:Hole","description":"A Hole is an opening in the surface of a Road, Track or Square such as road damages, manholes or drains. Holes can span multiple transportation objects.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the Hole.","type":"core:Code","maxOccurs":1}]}'
    WHERE ID = 611;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:AuxiliaryTrafficArea","description":"An AuxiliaryTrafficArea is the ground surface of an AuxiliaryTrafficSpace.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the AuxiliaryTrafficArea.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the intended purposes of the AuxiliaryTrafficArea.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the actual uses of the AuxiliaryTrafficArea.","type":"core:Code"},{"name":"surfaceMaterial","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the type of pavement of the AuxiliaryTrafficArea.","type":"core:Code","maxOccurs":1}]}'
    WHERE ID = 612;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:TrafficArea","description":"A TrafficArea is the ground surface of a TrafficSpace. Traffic areas are the surfaces upon which traffic actually takes place.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the TrafficArea.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the intended purposes of the TrafficArea.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the actual uses of the TrafficArea.","type":"core:Code"},{"name":"surfaceMaterial","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Specifies the type of pavement of the TrafficArea.","type":"core:Code","maxOccurs":1}]}'
    WHERE ID = 613;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"tran:Marking","description":"A Marking is a visible pattern on a transportation area relevant to the structuring or restriction of traffic. Examples are road markings and markings related to railway or waterway traffic.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/transportation/5.0","description":"Indicates the specific type of the Marking.","type":"core:Code","maxOccurs":1}]}'
    WHERE ID = 614;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"con:AbstractConstruction","description":"AbstractConstruction is the abstract superclass for objects that are manufactured by humans from construction materials, are connected to earth, and are intended to be permanent. A connection with the ground also exists when the construction rests by its own weight on the ground or is moveable limited on stationary rails or if the construction  is intended to be used mainly stationary.","table":"feature","properties":[{"name":"conditionOfConstruction","namespace":"http://3dcitydb.org/3dcitydb/construction/5.0","description":"Indicates the life-cycle status of the construction.","type":"core:String","maxOccurs":1},{"name":"dateOfConstruction","namespace":"http://3dcitydb.org/3dcitydb/construction/5.0","description":"Indicates the date at which the construction was completed.","type":"core:Timestamp","maxOccurs":1},{"name":"dateOfDemolition","namespace":"http://3dcitydb.org/3dcitydb/construction/5.0","description":"Indicates the date at which the construction was demolished.","type":"core:Timestamp","maxOccurs":1},{"name":"constructionEvent","namespace":"http://3dcitydb.org/3dcitydb/construction/5.0","description":"Describes specific events in the life-time of the construction.","type":"con:ConstructionEvent"},{"name":"elevation","namespace":"http://3dcitydb.org/3dcitydb/construction/5.0","description":"Specifies qualified elevations of the construction in relation to a well-defined surface which is commonly taken as origin (e.g. geoid or water level).","type":"con:Elevation"},{"name":"height","namespace":"http://3dcitydb.org/3dcitydb/construction/5.0","description":"Specifies qualified heights of the construction above ground or below ground.","type":"con:Height"},{"name":"occupancy","namespace":"http://3dcitydb.org/3dcitydb/construction/5.0","description":"Provides qualified information on the residency of persons, animals, or other moveable objects in the construction.","type":"core:Occupancy"}]}'
    WHERE ID = 700;

