    UPDATE objectclass
    SET SCHEMA = '{"identifier":"brid:AbstractBridge","description":"AbstractBridge is an abstract superclass representing the common attributes and associations of the classes Bridge and BridgePart.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Indicates the specific type of the Bridge or BridgePart.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the intended purposes of the Bridge or BridgePart.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the actual uses of the Bridge or BridgePart.","type":"core:Code"},{"name":"isMovable","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Indicates whether the Bridge or BridgePart can be moved to allow for watercraft to pass.","type":"core:Boolean","maxOccurs":1},{"name":"bridgeConstructiveElement","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Relates the constructive elements to the Bridge or BridgePart.","type":"core:FeatureProperty","target":"brid:BridgeConstructiveElement","relationType":"contains"},{"name":"bridgeInstallation","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Relates the installation objects to the Bridge or BridgePart.","type":"core:FeatureProperty","target":"brid:BridgeInstallation","relationType":"contains"},{"name":"bridgeRoom","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Relates the rooms to the Bridge or BridgePart.","type":"core:FeatureProperty","target":"brid:BridgeRoom","relationType":"contains"},{"name":"bridgeFurniture","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Relates the furniture objects to the Bridge or BridgePart.","type":"core:FeatureProperty","target":"brid:BridgeFurniture","relationType":"contains"},{"name":"address","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Relates the addresses to the Bridge or BridgePart.","type":"core:AddressProperty"},{"name":"lod1MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSurface geometry that represents the Bridge or BridgePart in Level of Detail 1. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod4MultiCurve","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiCurve geometry that represents the Bridge or BridgePart in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1},{"name":"lod4MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSurface geometry that represents the Bridge or BridgePart in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod4Solid","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D Solid geometry that represents the Bridge or BridgePart in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractSolid","maxOccurs":1},{"name":"lod4TerrainIntersectionCurve","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiCurve geometry that represents the terrain intersection curve of the Bridge or BridgePart in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1}]}'
    WHERE ID = 1000;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"brid:BridgeConstructiveElement","description":"A BridgeConstructiveElement is an element of a bridge which is essential from a structural point of view. Examples are pylons, anchorages, slabs, beams.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Indicates the specific type of the BridgeConstructiveElement.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the intended purposes of the BridgeConstructiveElement.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the actual uses of the BridgeConstructiveElement.","type":"core:Code"},{"name":"lod1Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the BridgeConstructiveElement in Level of Detail 1. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod2Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the BridgeConstructiveElement in Level of Detail 2. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod3Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the BridgeConstructiveElement in Level of Detail 3. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod4Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the BridgeConstructiveElement in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod4TerrainIntersectionCurve","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiCurve geometry that represents the terrain intersection curve of the BridgeConstructiveElement in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiLineString","maxOccurs":1},{"name":"lod4ImplicitRepresentation","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to an implicit geometry that represents the BridgeConstructiveElement in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:ImplicitGeometryProperty","maxOccurs":1}]}'
    WHERE ID = 1003;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"brid:BridgeRoom","description":"A BridgeRoom is a space within a Bridge or BridgePart intended for human occupancy (e.g. a place of work or recreation) and/or containment (storage) of animals or things. A BridgeRoom is bounded physically and/or virtually (e.g. by ClosureSurfaces or GenericSurfaces).","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Indicates the specific type of the BridgeRoom.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the intended purposes of the BridgeRoom.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the actual uses of the BridgeRoom.","type":"core:Code"},{"name":"bridgeFurniture","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Relates the furniture objects to the BridgeRoom.","type":"core:FeatureProperty","target":"brid:BridgeFurniture","relationType":"contains"},{"name":"bridgeInstallation","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Relates to the installation objects to the BridgeRoom.","type":"core:FeatureProperty","target":"brid:BridgeInstallation","relationType":"contains"},{"name":"lod4Solid","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D Solid geometry that represents the BridgeRoom in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractSolid","maxOccurs":1},{"name":"lod4MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSurface geometry that represents the BridgeRoom in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1}]}'
    WHERE ID = 1004;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"brid:BridgeInstallation","description":"A BridgeInstallation is a permanent part of a Bridge (inside and/or outside) which does not have the significance of a BridgePart. In contrast to BridgeConstructiveElements, a BridgeInstallation is not essential from a structural point of view. Examples are stairs, antennas or railways.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Indicates the specific type of the BridgeInstallation.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the intended purposes of the BridgeInstallation.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the actual uses of the BridgeInstallation.","type":"core:Code"},{"name":"lod2Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the BridgeInstallation in Level of Detail 2. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod3Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the BridgeInstallation in Level of Detail 3. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod4Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the BridgeInstallation in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod4ImplicitRepresentation","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to an implicit geometry that represents the BridgeInstallation in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:ImplicitGeometryProperty","maxOccurs":1}]}'
    WHERE ID = 1005;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"brid:BridgeFurniture","description":"A BridgeFurniture is an equipment for occupant use, usually not fixed to the bridge.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Indicates the specific type of the BridgeFurniture.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the intended purposes of the BridgeFurniture.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/bridge/5.0","description":"Specifies the actual uses of the BridgeFurniture.","type":"core:Code"},{"name":"lod4Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the BridgeFurniture in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod4ImplicitRepresentation","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to an implicit geometry that represents the BridgeFurniture in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:ImplicitGeometryProperty","maxOccurs":1}]}'
