    UPDATE objectclass
    SET SCHEMA = '{"identifier":"app:Appearance","description":"An Appearance is a collection of surface data, i.e. observable properties for surface geometry objects in the form of textures and material.","table":"appearance","properties":[{"name":"objectId","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the identifier of the appearance that is unique within the database. Using a globally unique identifier is recommended.","value":{"column":"objectid","type":"string"},"maxOccurs":1},{"name":"identifier","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies an optional identifier of the appearance that is globally unique.","value":{"column":"identifier","type":"string"},"maxOccurs":1},{"name":"codeSpace","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the code space of the identifier, typically a reference to the maintaining authority.","value":{"column":"identifier_codespace","type":"string"},"parent":1,"minOccurs":1,"maxOccurs":1},{"name":"theme","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the topic of the Appearance. Each Appearance contains surface data for one theme only. Examples of themes are infrared radiation, noise pollution, or earthquake-induced structural stress.","value":{"column":"theme","type":"string"},"maxOccurs":1},{"name":"isGlobal","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Indicates whether the Appearance is global, i.e. is not associated with a specific feature.","value":{"column":"is_global","type":"boolean"}},{"name":"surfaceData","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Relates to the surface data that are part of the Appearance.","target":"app:AbstractSurfaceData","joinTable":{"table":"appear_to_surface_data","sourceJoin":{"table":"appearance","fromColumn":"id","toColumn":"appearance_id"},"targetJoin":{"table":"surface_data","fromColumn":"surface_data_id","toColumn":"id","conditions":[{"column":"objectclass_id","value":"@target.objectclass_id@","type":"integer"}]}}}]}'
    WHERE ID = 1100;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"app:AbstractSurfaceData","description":"AbstractSurfaceData is the abstract superclass for different kinds of textures and material.","table":"surface_data","properties":[{"name":"objectId","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the identifier of the surface data that is unique within the database. Using a globally unique identifier is recommended.","value":{"column":"objectid","type":"string"},"maxOccurs":1},{"name":"identifier","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies an optional identifier of the surface data that is globally unique.","value":{"column":"identifier","type":"string"},"maxOccurs":1},{"name":"codeSpace","namespace":"http://3dcitydb.org/3dcitydb/core/5.0","description":"Specifies the code space of the identifier, typically a reference to the maintaining authority.","value":{"column":"identifier_codespace","type":"string"},"parent":1,"minOccurs":1,"maxOccurs":1},{"name":"isFront","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Indicates whether the texture or material is assigned to the front side or the back side of the surface geometry object.","value":{"column":"is_front","type":"boolean"},"maxOccurs":1}]}'
    WHERE ID = 1101;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"app:X3DMaterial","description":"X3DMaterial defines properties for surface geometry objects based on the material definitions from the X3D and COLLADA standards.","table":"surface_data","properties":[{"name":"ambientIntensity","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the minimum percentage of diffuseColor that is visible regardless of light sources.","value":{"column":"x3d_ambient_intensity","type":"double"},"maxOccurs":1},{"name":"diffuseColor","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the color of the light diffusely reflected by the surface geometry object.","value":{"column":"x3d_diffuse_color","type":"string"},"maxOccurs":1},{"name":"emissiveColor","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the color of the light emitted by the surface geometry object.","value":{"column":"x3d_emissive_color","type":"string"},"maxOccurs":1},{"name":"specularColor","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the color of the light directly reflected by the surface geometry object.","value":{"column":"x3d_specular_color","type":"string"},"maxOccurs":1},{"name":"shininess","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the sharpness of the specular highlight.","value":{"column":"x3d_shininess","type":"double"},"maxOccurs":1},{"name":"transparency","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the degree of transparency of the surface geometry object.","value":{"column":"x3d_transparency","type":"double"},"maxOccurs":1},{"name":"isSmooth","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies which interpolation method is used for the shading of the surface geometry object. If the attribute is set to true, vertex normals should be used for shading (Gouraud shading). Otherwise, normals should be constant for a surface patch (flat shading).","value":{"column":"x3d_is_smooth","type":"boolean"},"maxOccurs":1}]}'
    WHERE ID = 1102;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"app:AbstractTexture","description":"AbstractTexture is the abstract superclass to represent the common attributes of the classes ParameterizedTexture and GeoreferencedTexture.","table":"surface_data","properties":[{"name":"imageURI","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the URI that points to the external texture image.","value":{"column":"image_uri","type":"string"},"minOccurs":1,"maxOccurs":1,"join":{"table":"tex_image","fromColumn":"tex_image_id","toColumn":"id"}},{"name":"mimeType","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the MIME type of the texture image.","value":{"column":"mime_type","type":"string"},"maxOccurs":1,"join":{"table":"tex_image","fromColumn":"tex_image_id","toColumn":"id"}},{"name":"codeSpace","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the code space of the MIME type, typically a dictionary, thesaurus, classification scheme, authority, or pattern for the MIME type.","value":{"column":"mime_type_codespace","type":"string"},"parent":1,"maxOccurs":1},{"name":"textureType","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Indicates the specific type of the texture.","value":{"column":"tex_texture_type","type":"string"},"maxOccurs":1},{"name":"wrapMode","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the behaviour of the texture when the texture is smaller than the surface to which it is applied.","value":{"column":"tex_wrap_mode","type":"string"},"maxOccurs":1},{"name":"borderColor","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Specifies the color of that part of the surface that is not covered by the texture.","value":{"column":"tex_border_color","type":"string"},"maxOccurs":1}]}'
    WHERE ID = 1103;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"app:GeoreferencedTexture","description":"A GeoreferencedTexture is a texture that uses a planimetric projection. It contains an implicit parameterization that is either stored within the image file, an accompanying world file or specified using the orientation and referencePoint elements.","table":"surface_data","properties":[{"name":"referencePoint","namespace":"http://3dcitydb.org/3dcitydb/appearance/5.0","description":"Relates to the 2D Point geometry that represents the center of the upper left image pixel in world space.","value":{"column":"gt_reference_point","type":"core:Point"},"maxOccurs":1}]}'
    WHERE ID = 1105;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"grp:CityObjectGroup","description":"A CityObjectGroup represents an application-specific aggregation of city objects according to some user-defined criteria. Examples for groups are the buildings in a specific region, the result of a query, or objects put together for visualization purposes. Each member of a group may be qualified by a role name, reflecting the role each city object plays in the context of the group.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/cityobjectgroup/5.0","description":"Indicates the specific type of the CityObjectGroup.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/cityobjectgroup/5.0","description":"Specifies the intended purposes of the CityObjectGroup.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/cityobjectgroup/5.0","description":"Specifies the actual usages of the CityObjectGroup.","type":"core:Code"},{"name":"groupMember","namespace":"http://3dcitydb.org/3dcitydb/cityobjectgroup/5.0","description":"Relates to the city objects that are part of the CityObjectGroup and indicates their role.","type":"grp:Role"},{"name":"parent","namespace":"http://3dcitydb.org/3dcitydb/cityobjectgroup/5.0","description":"Relates to a city object to which the CityObjectGroup belongs.","type":"core:FeatureProperty","target":"core:AbstractCityObject","relationType":"relates","maxOccurs":1},{"name":"geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the CityObjectGroup. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry"}]}'
    WHERE ID = 1200;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"veg:SolitaryVegetationObject","description":"A SolitaryVegetationObject represents individual vegetation objects, e.g. trees or bushes.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Indicates the specific type of the SolitaryVegetationObject.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the intended purposes of the SolitaryVegetationObject.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the actual uses of the SolitaryVegetationObject.","type":"core:Code"},{"name":"species","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Indicates the botanical name of the SolitaryVegetationObject.","type":"core:Code","maxOccurs":1},{"name":"height","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Distance between the highest point of the vegetation object and the lowest point of the terrain at the bottom of the object.","type":"core:Measure","maxOccurs":1},{"name":"trunkDiameter","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the diameter of the SolitaryCityObject''s trunk.","type":"core:Measure","maxOccurs":1},{"name":"crownDiameter","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the diameter of the SolitaryCityObject''s crown.","type":"core:Measure","maxOccurs":1},{"name":"rootBallDiameter","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the diameter of the SolitaryCityObject''s root ball.","type":"core:Measure","maxOccurs":1},{"name":"maxRootBallDepth","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the vertical distance between the lowest point of the SolitaryVegetationObject''s root ball and the terrain surface.","type":"core:Measure","maxOccurs":1},{"name":"lod1Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the SolitaryVegetationObject in Level of Detail 1. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod2Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the SolitaryVegetationObject in Level of Detail 2. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod3Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the SolitaryVegetationObject in Level of Detail 3. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod4Geometry","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D geometry that represents the SolitaryVegetationObject in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:AbstractGeometry","maxOccurs":1},{"name":"lod4ImplicitRepresentation","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to an implicit geometry that represents the SolitaryVegetationObject in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:ImplicitGeometryProperty","maxOccurs":1}]}'
    WHERE ID = 1301;

    UPDATE objectclass
    SET SCHEMA = '{"identifier":"veg:PlantCover","description":"A PlantCover represents a space covered by vegetation.","table":"feature","properties":[{"name":"class","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Indicates the specific type of the PlantCover.","type":"core:Code","maxOccurs":1},{"name":"function","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the intended purposes of the PlantCover.","type":"core:Code"},{"name":"usage","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the actual uses of the PlantCover.","type":"core:Code"},{"name":"averageHeight","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the average height of the PlantCover.","type":"core:Measure","maxOccurs":1},{"name":"minHeight","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the minimum height of the PlantCover.","type":"core:Measure","maxOccurs":1},{"name":"maxHeight","namespace":"http://3dcitydb.org/3dcitydb/vegetation/5.0","description":"Specifies the maximum height of the PlantCover.","type":"core:Measure","maxOccurs":1},{"name":"lod1MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSurface geometry that represents the PlantCover in Level of Detail 1. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod4MultiSurface","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSurface geometry that represents the PlantCover in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSurface","maxOccurs":1},{"name":"lod1MultiSolid","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSolid geometry that represents the PlantCover in Level of Detail 1. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSolid","maxOccurs":1},{"name":"lod2MultiSolid","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSolid geometry that represents the PlantCover in Level of Detail 2. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSolid","maxOccurs":1},{"name":"lod3MultiSolid","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSolid geometry that represents the PlantCover in Level of Detail 3. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSolid","maxOccurs":1},{"name":"lod4MultiSolid","namespace":"http://3dcitydb.org/3dcitydb/deprecated/5.0","description":"Relates to a 3D MultiSolid geometry that represents the PlantCover in Level of Detail 4. Deprecated since CityGML 3.0.","type":"core:GeometryProperty","target":"core:MultiSolid","maxOccurs":1}]}'
