    UPDATE datatype
    SET SCHEMA = '{"identifier":"dyn:SensorConnection","description":"A SensorConnection provides all details that are required to retrieve a specific data stream from an external sensor web service. This data type comprises the service type (e.g. OGC SensorThings API, OGC Sensor Observation Services, MQTT, proprietary platforms), the URL of the sensor service, the identifier for the sensor or thing, and its observed property as well as information about the required authentication method.","table":"property","properties":[{"name":"connectionType","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Indicates the type of Sensor API to which the SensorConnection refers.","type":"core:Code","minOccurs":1,"maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"observationProperty","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the phenomenon for which the SensorConnection provides observations.","type":"core:String","minOccurs":1,"maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"uom","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the unit of measurement of the observations.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"sensorID","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the unique identifier of the sensor from which the SensorConnection retrieves observations.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"sensorName","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the name of the sensor from which the SensorConnection retrieves observations.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"observationID","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the unique identifier of the observation that is retrieved by the SensorConnection.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"datastreamID","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the datastream that is retrieved by the SensorConnection.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"baseURL","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the base URL of the Sensor API request.","type":"core:URI","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"authType","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the type of authentication required to be able to access the Sensor API.","type":"core:Code","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"mqttServer","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the name of the MQTT Server. This attribute is relevant when the MQTT Protocol is used to connect to a Sensor API.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"mqttTopic","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Names the specific datastream that is retrieved by the SensorConnection. This attribute is relevant when the MQTT Protocol is used to connect to a Sensor API.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"linkToObservation","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the complete URL to the observation request.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"linkToSensorDescription","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Specifies the complete URL to the sensor description request.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"sensorLocation","namespace":"http://3dcitydb.org/3dcitydb/dynamizer/5.0","description":"Relates the sensor to the city object where it is located.","type":"core:FeatureProperty","target":"core:AbstractCityObject","relationType":"relates","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}}]}'
