    SET SCHEMA = '{"identifier":"bldg:RoomHeight","description":"The RoomHeight represents a vertical distance (measured or estimated) between a low reference and a high reference.","table":"property","value":{"property":3},"properties":[{"name":"highReference","namespace":"http://3dcitydb.org/3dcitydb/building/5.0","description":"Indicates the high point used to calculate the value of the room height.","type":"core:Code","minOccurs":1,"maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"lowReference","namespace":"http://3dcitydb.org/3dcitydb/building/5.0","description":"Indicates the low point used to calculate the value of the room height.","type":"core:Code","minOccurs":1,"maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"status","namespace":"http://3dcitydb.org/3dcitydb/building/5.0","description":"Indicates the way the room height has been captured.","type":"core:String","minOccurs":1,"maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"value","namespace":"http://3dcitydb.org/3dcitydb/building/5.0","description":"Specifies the value of the room height.","type":"core:Measure","minOccurs":1,"maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}}]}'
    WHERE ID = 900;

    UPDATE datatype
    SET SCHEMA = '{"identifier":"grp:Role","description":"Role qualifies the function of a city object within the CityObjectGroup.","table":"property","properties":[{"name":"groupMember","namespace":"http://3dcitydb.org/3dcitydb/cityobjectgroup/5.0","description":"Relates to the city objects that are part of the CityObjectGroup.","type":"core:FeatureProperty","target":"core:AbstractCityObject","relationType":"relates","join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"role","namespace":"http://3dcitydb.org/3dcitydb/cityobjectgroup/5.0","description":"Describes the role the city object plays within the CityObjectGroup.","type":"core:String","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}}]}'
    WHERE ID = 1200;

    UPDATE datatype
    SET SCHEMA = '{"identifier":"vers:Transaction","description":"Transaction represents a modification of the city model by the creation, termination, or replacement of a specific city object. While the creation of a city object also marks its first object version, the termination marks the end of existence of a real world object and, hence, also terminates the final version of a city object. The replacement of a city object means that a specific version of it is replaced by a new version.","table":"property","properties":[{"name":"type","namespace":"http://3dcitydb.org/3dcitydb/versioning/5.0","description":"Indicates the specific type of the Transaction.","type":"core:String","minOccurs":1,"maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"oldFeature","namespace":"http://3dcitydb.org/3dcitydb/versioning/5.0","description":"Relates to the version of the city object prior to the Transaction.","type":"core:FeatureProperty","target":"core:AbstractFeatureWithLifespan","relationType":"relates","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}},{"name":"newFeature","namespace":"http://3dcitydb.org/3dcitydb/versioning/5.0","description":"Relates to the version of the city object subsequent to the Transaction.","type":"core:FeatureProperty","target":"core:AbstractFeatureWithLifespan","relationType":"relates","maxOccurs":1,"join":{"table":"property","fromColumn":"id","toColumn":"parent_id"}}]}'
    WHERE ID = 1400;
  END LOOP;
END
$$;

SELECT format($sql$
SET search_path TO %I, citydb_pkg, public;

DO $$
BEGIN
  RAISE NOTICE E'Re-creating changelog triggers on "feature" table ...\n';
END
$$;

DROP TRIGGER IF EXISTS feature_changelog_trigger ON feature;

CREATE OR REPLACE FUNCTION log_feature_changes() RETURNS TRIGGER AS
$body$
DECLARE
  v_feature_id bigint;
  v_changelog_feature_id bigint;
  v_is_toplevel integer;
  v_objectclass_id integer;
  v_objectid text;
  v_identifier text;
  v_identifier_codespace text;
  v_envelope geometry;
  v_reason_for_update text;
  v_transaction_type text;
BEGIN
  v_transaction_type := TG_OP;

  IF v_transaction_type = 'UPDATE' AND OLD.last_modification_date IS NOT DISTINCT FROM NEW.last_modification_date THEN
    RETURN NULL;
  END IF;

  IF v_transaction_type = 'DELETE' THEN
    v_feature_id := OLD.id;
    v_changelog_feature_id := NULL;
    v_objectclass_id := OLD.objectclass_id;
    v_objectid := OLD.objectid;
    v_identifier := OLD.identifier;
    v_identifier_codespace := OLD.identifier_codespace;
    v_envelope := OLD.envelope;
    v_reason_for_update := NULL;
  ELSE
    v_feature_id := NEW.id;
    v_changelog_feature_id := v_feature_id;
    v_objectclass_id := NEW.objectclass_id;
    v_objectid := NEW.objectid;
    v_identifier := NEW.identifier;
    v_identifier_codespace := NEW.identifier_codespace;
    v_envelope := NEW.envelope;
    v_reason_for_update := NEW.reason_for_update;

    IF NEW.termination_date IS NOT NULL THEN
      v_transaction_type := 'TERMINATE';
    END IF;
  END IF;

  SELECT is_toplevel
  INTO v_is_toplevel
  FROM objectclass o
  WHERE id = v_objectclass_id;

  IF v_is_toplevel = 1
     AND (v_objectclass_id <> 203 OR NOT EXISTS (
       SELECT 1
       FROM property p
       WHERE p.val_feature_id = v_feature_id
         AND p.val_relation_type = 1
     )) THEN
    INSERT INTO feature_changelog (
      feature_id, objectclass_id, objectid, identifier, identifier_codespace,
      envelope, transaction_type, transaction_date, db_user, reason_for_update
    ) VALUES (
      v_changelog_feature_id, v_objectclass_id, v_objectid, v_identifier, v_identifier_codespace,
      v_envelope, v_transaction_type, now(), user, v_reason_for_update
    );
  END IF;

  IF v_transaction_type = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$body$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER feature_changelog_delete_trigger
  BEFORE DELETE ON feature
  FOR EACH ROW EXECUTE PROCEDURE log_feature_changes();

CREATE OR REPLACE TRIGGER feature_changelog_insert_update_trigger
  AFTER INSERT OR UPDATE ON feature
  FOR EACH ROW EXECUTE PROCEDURE log_feature_changes();

$sql$, nspname)
FROM pg_catalog.pg_class c
JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
WHERE c.relname = 'feature_changelog' AND c.relkind = 'r'
\gexec
